insert into template.locales (code, label, language, tradition, version)
insert into template.vendor_questions
  (locale, category_key, category_label, "group", seq, question, why_it_matters)
values
  ('poruwa', 'venue_hotel', 'VENUE / HOTEL', 'money'::vendor_question_group, 1, 'Package rate per head for adults - and exactly what does it cover?', 'The headline number is meaningless until you know what is inside it.'),
  ('poruwa', 'venue_hotel', 'VENUE / HOTEL', 'money'::vendor_question_group, 2, 'Minimum guaranteed guests you must pay for, even if fewer come', 'You pay this whether they turn up or not. It sets your real floor price.'),
  ('poruwa', 'venue_hotel', 'VENUE / HOTEL', 'money'::vendor_question_group, 3, 'Rate for children, and up to what age is a child a child?', 'Some hotels charge full price from age 6, others from 12.'),
  ('poruwa', 'venue_hotel', 'VENUE / HOTEL', 'money'::vendor_question_group, 4, 'Are service charge and taxes (VAT / SSCL / TDL) included or added on top?', 'Adding these later can lift a quote by 25-30%.'),
  ('poruwa', 'venue_hotel', 'VENUE / HOTEL', 'money'::vendor_question_group, 5, 'Charge per extra hour beyond the agreed finish time', 'Sri Lankan receptions run late. Agree this before, not at midnight.'),
  ('poruwa', 'venue_hotel', 'VENUE / HOTEL', 'money'::vendor_question_group, 6, 'Corkage per bottle - hard liquor, beer and wine separately', 'Corkage can cost more than the alcohol itself.'),
  ('poruwa', 'venue_hotel', 'VENUE / HOTEL', 'money'::vendor_question_group, 7, 'Is there a minimum bar spend?', 'A minimum can force you to buy drink you do not need.'),
  ('poruwa', 'venue_hotel', 'VENUE / HOTEL', 'money'::vendor_question_group, 8, 'Do vendors and crew count in the head count, and what is the crew meal rate?', '20 crew at full guest rate is a large hidden line.'),
  ('poruwa', 'venue_hotel', 'VENUE / HOTEL', 'included'::vendor_question_group, 9, 'Which halls / areas, and the exact seated capacity WITH a Poruwa and dance floor', 'Stated capacity is usually theatre style, not a seated wedding.'),
  ('poruwa', 'venue_hotel', 'VENUE / HOTEL', 'included'::vendor_question_group, 10, 'Is the bridal suite included? Check-in time on the day and check-out next day', 'You need the room from mid-morning for dressing, not from 2pm.'),
  ('poruwa', 'venue_hotel', 'VENUE / HOTEL', 'included'::vendor_question_group, 11, 'Is a getting-ready room for the groom included or charged?', 'Often forgotten and then charged on the day.'),
  ('poruwa', 'venue_hotel', 'VENUE / HOTEL', 'included'::vendor_question_group, 12, 'How many complimentary rooms, and the group rate for extra rooms?', 'Matters if you have outstation or overseas family.'),
  ('poruwa', 'venue_hotel', 'VENUE / HOTEL', 'included'::vendor_question_group, 13, 'Are tables, chairs, linen and chair covers included, or does the decorator supply them?', 'Double-charging here is common.'),
  ('poruwa', 'venue_hotel', 'VENUE / HOTEL', 'included'::vendor_question_group, 14, 'Is a menu tasting included, and for how many people?', 'Ask before signing - afterwards it becomes a paid extra.'),
  ('poruwa', 'venue_hotel', 'VENUE / HOTEL', 'logistics'::vendor_question_group, 15, 'Is there another wedding at the hotel the same day, and in which hall?', 'Shared lobbies, shared parking and clashing music.'),
  ('poruwa', 'venue_hotel', 'VENUE / HOTEL', 'logistics'::vendor_question_group, 16, 'From what time can the decorator start? Is there an event in the hall that morning?', 'A Poruwa needs hours. A morning event can kill your setup window.'),
  ('poruwa', 'venue_hotel', 'VENUE / HOTEL', 'logistics'::vendor_question_group, 17, 'Is a Poruwa allowed in the hall - any limits on size, height or fixings?', 'Some ballrooms forbid anything fixed to the floor or ceiling.'),
  ('poruwa', 'venue_hotel', 'VENUE / HOTEL', 'logistics'::vendor_question_group, 18, 'Are Hewisi drummers and Kandyan dancers allowed indoors? Any sound limit?', 'Some hotels restrict drums indoors or after a certain hour.'),
  ('poruwa', 'venue_hotel', 'VENUE / HOTEL', 'logistics'::vendor_question_group, 19, 'What time must music stop?', 'Drives your whole reception running order.'),
  ('poruwa', 'venue_hotel', 'VENUE / HOTEL', 'logistics'::vendor_question_group, 20, 'Generator backup - is switchover automatic, and how many seconds?', 'A manual generator means minutes of darkness mid-ceremony.'),
  ('poruwa', 'venue_hotel', 'VENUE / HOTEL', 'logistics'::vendor_question_group, 21, 'Air conditioning - included, and running until what time?', 'AC being switched off at 11pm empties a dance floor fast.'),
  ('poruwa', 'venue_hotel', 'VENUE / HOTEL', 'logistics'::vendor_question_group, 22, 'How many parking spaces, and is parking charged to guests?', 'Guests paying for parking at your wedding reflects on you.'),
  ('poruwa', 'venue_hotel', 'VENUE / HOTEL', 'logistics'::vendor_question_group, 23, 'Is an outside caterer or outside cake allowed, and is there a charge?', 'Decides whether you can use your own baker at all.'),
  ('poruwa', 'venue_hotel', 'VENUE / HOTEL', 'risk'::vendor_question_group, 24, 'Booking deposit - how much, and is any of it refundable?', 'Usually not. Know the number before you commit the date.'),
  ('poruwa', 'venue_hotel', 'VENUE / HOTEL', 'risk'::vendor_question_group, 25, 'Cancellation and postponement policy - what if the date has to move?', 'The single most important clause in the contract.'),
  ('poruwa', 'venue_hotel', 'VENUE / HOTEL', 'risk'::vendor_question_group, 26, 'By when must the final guest number be confirmed, and can it go down?', 'Most venues let it go up but never down.'),
  ('poruwa', 'venue_hotel', 'VENUE / HOTEL', 'risk'::vendor_question_group, 27, 'Is the quotation itemised and in writing, with the taxes shown separately?', 'A one-line quote is where disputes start.'),
  ('poruwa', 'caterer', 'CATERER', 'money'::vendor_question_group, 1, 'Rate per head, and the exact menu at that rate', 'Menus get quietly downgraded between quote and wedding.'),
  ('poruwa', 'caterer', 'CATERER', 'money'::vendor_question_group, 2, 'Minimum number of guests', 'Sets your floor price.'),
  ('poruwa', 'caterer', 'CATERER', 'money'::vendor_question_group, 3, 'Crew and vendor meal rate', 'Photographers, dancers and drivers all need feeding.'),
  ('poruwa', 'caterer', 'CATERER', 'money'::vendor_question_group, 4, 'Transport charge to the venue', 'Often excluded from the per-head rate.'),
  ('poruwa', 'caterer', 'CATERER', 'included'::vendor_question_group, 5, 'Does it include rice, at least three vegetarian mains, dhal, mallum and papadam?', 'The staples are what guests actually judge.'),
  ('poruwa', 'caterer', 'CATERER', 'included'::vendor_question_group, 6, 'Is a live station (hoppers or kottu) included or extra?', 'Popular, and almost always an extra.'),
  ('poruwa', 'caterer', 'CATERER', 'included'::vendor_question_group, 7, 'How many desserts, and is watalappan included?', 'A Sri Lankan wedding without watalappan gets noticed.'),
  ('poruwa', 'caterer', 'CATERER', 'included'::vendor_question_group, 8, 'Do they supply crockery, cutlery, linen and chafing dishes?', 'If not, you are hiring them separately.'),
  ('poruwa', 'caterer', 'CATERER', 'included'::vendor_question_group, 9, 'How many service staff per 100 guests?', 'Under-staffing shows as long buffet queues.'),
  ('poruwa', 'caterer', 'CATERER', 'included'::vendor_question_group, 10, 'Are welcome drinks and short eats included?', 'Guests arrive up to an hour before the ceremony.'),
  ('poruwa', 'caterer', 'CATERER', 'included'::vendor_question_group, 11, 'Is a tasting included - when, and for how many people?', 'Taste before you pay the balance, not after.'),
  ('poruwa', 'caterer', 'CATERER', 'logistics'::vendor_question_group, 12, 'What time do they arrive, and how long do they need to set up?', 'Feeds straight into 21 Vendor Schedule.'),
  ('poruwa', 'caterer', 'CATERER', 'logistics'::vendor_question_group, 13, 'How are vegetarian, halal and allergy meals kept separate and labelled?', 'Cross-contamination is a real risk at a buffet.'),
  ('poruwa', 'caterer', 'CATERER', 'logistics'::vendor_question_group, 14, 'Who clears up, and by what time?', 'The venue will charge you if the caterer leaves a mess.'),
  ('poruwa', 'caterer', 'CATERER', 'risk'::vendor_question_group, 15, 'What happens if more guests arrive than confirmed?', 'Ask what buffer they hold and at what price.'),
  ('poruwa', 'caterer', 'CATERER', 'risk'::vendor_question_group, 16, 'Deposit, payment schedule and cancellation terms', 'Get it in writing.'),
  ('poruwa', 'photographer', 'PHOTOGRAPHER', 'money'::vendor_question_group, 1, 'Total price and exactly how many hours of coverage it buys', 'Coverage hours are the thing people forget to check.'),
  ('poruwa', 'photographer', 'PHOTOGRAPHER', 'money'::vendor_question_group, 2, 'Charge per extra hour', 'You will almost certainly run over.'),
  ('poruwa', 'photographer', 'PHOTOGRAPHER', 'money'::vendor_question_group, 3, 'Is the pre-shoot included? Any travel charge for the location?', 'Out-of-Colombo locations attract travel and stay costs.'),
  ('poruwa', 'photographer', 'PHOTOGRAPHER', 'money'::vendor_question_group, 4, 'Cost of parent albums and enlargements', 'Both sets of parents will want one.'),
  ('poruwa', 'photographer', 'PHOTOGRAPHER', 'money'::vendor_question_group, 5, 'Cost to receive the raw / unedited files', 'Some studios never release them. Ask now.'),
  ('poruwa', 'photographer', 'PHOTOGRAPHER', 'included'::vendor_question_group, 6, 'How many photographers and assistants are included on the day?', 'One person cannot cover a Poruwa and a groom''s entrance.'),
  ('poruwa', 'photographer', 'PHOTOGRAPHER', 'included'::vendor_question_group, 7, 'How many edited images do we receive, and how are they delivered?', '''Selected images'' can mean 200 or 2,000.'),
  ('poruwa', 'photographer', 'PHOTOGRAPHER', 'included'::vendor_question_group, 8, 'Album specification - size, number of spreads, cover, print lab', 'This is the thing you keep for 40 years.'),
  ('poruwa', 'photographer', 'PHOTOGRAPHER', 'included'::vendor_question_group, 9, 'Is a same-day edit offered, and what does the venue need to provide?', 'Needs a screen and a slot in the running order.'),
  ('poruwa', 'photographer', 'PHOTOGRAPHER', 'included'::vendor_question_group, 10, 'Drone - do they have one and a licensed operator?', 'Many venues and all airport-adjacent areas restrict drones.'),
  ('poruwa', 'photographer', 'PHOTOGRAPHER', 'logistics'::vendor_question_group, 11, 'Who exactly will shoot our wedding - the person we are meeting?', 'Big studios assign whoever is free. Get the name in the contract.'),
  ('poruwa', 'photographer', 'PHOTOGRAPHER', 'logistics'::vendor_question_group, 12, 'Can we see TWO complete weddings, start to finish - not just highlights?', 'A 30-image highlight reel hides a weak photographer.'),
  ('poruwa', 'photographer', 'PHOTOGRAPHER', 'logistics'::vendor_question_group, 13, 'Will they work to our shot list on 18 Photo & Video Plan?', 'Family group shots get missed unless they are written down.'),
  ('poruwa', 'photographer', 'PHOTOGRAPHER', 'logistics'::vendor_question_group, 14, 'How do they work alongside the videographer?', 'Two teams competing for position ruins both sets of results.'),
  ('poruwa', 'photographer', 'PHOTOGRAPHER', 'logistics'::vendor_question_group, 15, 'Do they need a meal and somewhere to change?', 'Plan it rather than be asked on the night.'),
  ('poruwa', 'photographer', 'PHOTOGRAPHER', 'logistics'::vendor_question_group, 16, 'Delivery timeline - previews, full gallery, and the finished album', 'Six months is normal; twelve is not. Put it in writing.'),
  ('poruwa', 'photographer', 'PHOTOGRAPHER', 'risk'::vendor_question_group, 17, 'Backup equipment - two bodies, and cameras with dual card slots?', 'A single card failure loses your wedding.'),
  ('poruwa', 'photographer', 'PHOTOGRAPHER', 'risk'::vendor_question_group, 18, 'How and where do they back up the files, and for how long do they keep them?', 'Ask how long before they delete your wedding.'),
  ('poruwa', 'photographer', 'PHOTOGRAPHER', 'risk'::vendor_question_group, 19, 'What happens if they fall ill - is there a named substitute?', 'Ask before, not on the morning.'),
  ('poruwa', 'photographer', 'PHOTOGRAPHER', 'risk'::vendor_question_group, 20, 'Deposit, payment schedule and cancellation terms', 'Get it in writing.'),
  ('poruwa', 'videographer', 'VIDEOGRAPHER', 'money'::vendor_question_group, 1, 'Total price, hours of coverage, and the extra-hour rate', 'Same trap as photography.'),
  ('poruwa', 'videographer', 'VIDEOGRAPHER', 'money'::vendor_question_group, 2, 'Cost of the full-length edit if only a highlight film is quoted', 'Most packages quote the highlight only.'),
  ('poruwa', 'videographer', 'VIDEOGRAPHER', 'money'::vendor_question_group, 3, 'Cost of raw footage and the storage drive', 'Raw footage is large and usually charged.'),
  ('poruwa', 'videographer', 'VIDEOGRAPHER', 'money'::vendor_question_group, 4, 'Live streaming for overseas family - cost and what it needs', 'Common for Sri Lankan families abroad. Needs bandwidth.'),
  ('poruwa', 'videographer', 'VIDEOGRAPHER', 'included'::vendor_question_group, 5, 'How many videographers and cameras on the day?', 'One camera cannot cover a Poruwa properly.'),
  ('poruwa', 'videographer', 'VIDEOGRAPHER', 'included'::vendor_question_group, 6, 'Highlight film length, and is a full ceremony edit included?', 'Ask to see both, not just the trailer.'),
  ('poruwa', 'videographer', 'VIDEOGRAPHER', 'included'::vendor_question_group, 7, 'How do they record the Ashtaka and the vows - which microphones?', 'Poruwa chanting recorded from ten metres away is unusable.'),
  ('poruwa', 'videographer', 'VIDEOGRAPHER', 'included'::vendor_question_group, 8, 'Will they mic the officiant and the MC?', 'The audio is what makes the film watchable later.'),
  ('poruwa', 'videographer', 'VIDEOGRAPHER', 'included'::vendor_question_group, 9, 'Drone footage - included or extra?', 'Ask about venue restrictions at the same time.'),
  ('poruwa', 'videographer', 'VIDEOGRAPHER', 'logistics'::vendor_question_group, 10, 'Can we watch TWO full films end to end, not a three-minute reel?', 'Reels are cut from the best ten seconds of a whole day.'),
  ('poruwa', 'videographer', 'VIDEOGRAPHER', 'logistics'::vendor_question_group, 11, 'What lighting do they bring, and will it be intrusive during the ceremony?', 'Harsh video lights ruin the photographs and the mood.'),
  ('poruwa', 'videographer', 'VIDEOGRAPHER', 'logistics'::vendor_question_group, 12, 'Who is the lead shooter on our day?', 'Get the name written into the contract.'),
  ('poruwa', 'videographer', 'VIDEOGRAPHER', 'logistics'::vendor_question_group, 13, 'Delivery format and timeline', 'Ask for a date, not ''a few months''.'),
  ('poruwa', 'videographer', 'VIDEOGRAPHER', 'risk'::vendor_question_group, 14, 'Do they record to two cards or two devices simultaneously?', 'Audio and video backup matter more here than in photography.'),
  ('poruwa', 'videographer', 'VIDEOGRAPHER', 'risk'::vendor_question_group, 15, 'Is the music in the film properly licensed?', 'Unlicensed tracks get films muted on social media.'),
  ('poruwa', 'videographer', 'VIDEOGRAPHER', 'risk'::vendor_question_group, 16, 'Deposit, payment schedule and cancellation terms', 'Get it in writing.'),
  ('poruwa', 'decorator_florist', 'DECORATOR / FLORIST', 'money'::vendor_question_group, 1, 'Is the quoted price for the exact design shown, or ''something similar''?', 'This is the single biggest source of decor disappointment.'),
  ('poruwa', 'decorator_florist', 'DECORATOR / FLORIST', 'money'::vendor_question_group, 2, 'How many guest table centrepieces are included?', 'Priced per table - check it matches your table count.'),
  ('poruwa', 'decorator_florist', 'DECORATOR / FLORIST', 'money'::vendor_question_group, 3, 'Are chair covers and sashes included, or charged per chair?', '200 chairs at even a small rate adds up fast.'),
  ('poruwa', 'decorator_florist', 'DECORATOR / FLORIST', 'money'::vendor_question_group, 4, 'Cost of lighting - uplighting, fairy lights, spotlight on the Poruwa', 'Lighting is usually a separate line and it transforms a room.'),
  ('poruwa', 'decorator_florist', 'DECORATOR / FLORIST', 'included'::vendor_question_group, 5, 'Can we see photos of Poruwas they have actually built themselves?', 'Ask for their own work, not Pinterest references.'),
  ('poruwa', 'decorator_florist', 'DECORATOR / FLORIST', 'included'::vendor_question_group, 6, 'Is the Poruwa structure theirs or hired in? What are its dimensions?', 'The venue needs the dimensions; some halls restrict them.'),
  ('poruwa', 'decorator_florist', 'DECORATOR / FLORIST', 'included'::vendor_question_group, 7, 'Which parts are fresh flowers and which are artificial?', 'Be told now rather than notice on the day.'),
  ('poruwa', 'decorator_florist', 'DECORATOR / FLORIST', 'included'::vendor_question_group, 8, 'Which specific flowers - and what is the substitute if they are unavailable?', 'Seasonal and import availability changes.'),
  ('poruwa', 'decorator_florist', 'DECORATOR / FLORIST', 'included'::vendor_question_group, 9, 'Are the backdrop, stage and head table included?', 'Frequently quoted separately.'),
  ('poruwa', 'decorator_florist', 'DECORATOR / FLORIST', 'included'::vendor_question_group, 10, 'Entrance arch, welcome board, seating chart board and signage - included?', 'Small items that add up if excluded.'),
  ('poruwa', 'decorator_florist', 'DECORATOR / FLORIST', 'included'::vendor_question_group, 11, 'Who supplies the oil lamp, kalasa pots, betel tray and white cloth?', 'Decorator or family - agree it, or nobody brings them.'),
  ('poruwa', 'decorator_florist', 'DECORATOR / FLORIST', 'included'::vendor_question_group, 12, 'Who supplies the ceremony items - coconut, thread, kiribath tray?', 'Usually the family. Confirm so it lands on 23 Procurement.'),
  ('poruwa', 'decorator_florist', 'DECORATOR / FLORIST', 'logistics'::vendor_question_group, 13, 'What time do they start setting up, and when will it be finished?', 'Set a sign-off deadline before guests arrive.'),
  ('poruwa', 'decorator_florist', 'DECORATOR / FLORIST', 'logistics'::vendor_question_group, 14, 'Have they worked at this venue before? Have they done a site visit?', 'Someone who knows the hall makes fewer mistakes.'),
  ('poruwa', 'decorator_florist', 'DECORATOR / FLORIST', 'logistics'::vendor_question_group, 15, 'Who removes everything, and when?', 'Breakdown overruns get charged to you by the venue.'),
  ('poruwa', 'decorator_florist', 'DECORATOR / FLORIST', 'risk'::vendor_question_group, 16, 'What is the plan if it rains and part of the decor is outdoors?', 'Have the answer in writing before you pay.'),
  ('poruwa', 'decorator_florist', 'DECORATOR / FLORIST', 'risk'::vendor_question_group, 17, 'Any damage deposit held by the venue, and who is liable?', 'Clarify between decorator and venue, not after.'),
  ('poruwa', 'decorator_florist', 'DECORATOR / FLORIST', 'risk'::vendor_question_group, 18, 'Deposit, payment schedule and final design sign-off date', 'Lock the design so it cannot drift.'),
  ('poruwa', 'bridal_dresser', 'BRIDAL DRESSER', 'money'::vendor_question_group, 1, 'Total price - and is the trial included or charged separately?', 'Trials are often billed as an extra.'),
  ('poruwa', 'bridal_dresser', 'BRIDAL DRESSER', 'money'::vendor_question_group, 2, 'Rate per additional person for bridesmaids and mothers', 'Adds up quickly across a bridal party.'),
  ('poruwa', 'bridal_dresser', 'BRIDAL DRESSER', 'money'::vendor_question_group, 3, 'Travel charge to the hotel, and do they need a room?', 'If they need a room, someone has to pay for it.'),
  ('poruwa', 'bridal_dresser', 'BRIDAL DRESSER', 'included'::vendor_question_group, 4, 'Kandyan bridal dressing, western, or both? Can they do both looks?', 'Not every artist does traditional osari dressing well.'),
  ('poruwa', 'bridal_dresser', 'BRIDAL DRESSER', 'included'::vendor_question_group, 5, 'Do they drape the saree, or do we need a separate dresser?', 'A very common gap - the makeup artist may not drape.'),
  ('poruwa', 'bridal_dresser', 'BRIDAL DRESSER', 'included'::vendor_question_group, 6, 'Do they supply the nalalpata and hair jewellery, or must we?', 'If not, it goes on the jewellery list.'),
  ('poruwa', 'bridal_dresser', 'BRIDAL DRESSER', 'included'::vendor_question_group, 7, 'Do they stay for touch-ups through the evening, and until when?', 'Photographs at 10pm look very different without touch-ups.'),
  ('poruwa', 'bridal_dresser', 'BRIDAL DRESSER', 'included'::vendor_question_group, 8, 'Will they change the bride into the going-away outfit?', 'Needs time in the running order either way.'),
  ('poruwa', 'bridal_dresser', 'BRIDAL DRESSER', 'logistics'::vendor_question_group, 9, 'Who actually does the bride - the named artist or an assistant?', 'Studios rotate staff. Name them in the booking.'),
  ('poruwa', 'bridal_dresser', 'BRIDAL DRESSER', 'logistics'::vendor_question_group, 10, 'How long do they need for the bride, and what time will they arrive?', 'Bridal dressing running late delays the entire day.'),
  ('poruwa', 'bridal_dresser', 'BRIDAL DRESSER', 'logistics'::vendor_question_group, 11, 'How many weddings do they take on the same day?', 'Three bookings in one day means you get rushed.'),
  ('poruwa', 'bridal_dresser', 'BRIDAL DRESSER', 'logistics'::vendor_question_group, 12, 'Can we see photographs of brides with a similar skin tone?', 'Colour matching is the most common complaint.'),
  ('poruwa', 'bridal_dresser', 'BRIDAL DRESSER', 'risk'::vendor_question_group, 13, 'Which products do they use - any known allergies or sensitivities?', 'Test at the trial, not on the morning.'),
  ('poruwa', 'bridal_dresser', 'BRIDAL DRESSER', 'risk'::vendor_question_group, 14, 'What happens if they are ill - is there a named substitute?', 'Nobody plans for this and it does happen.'),
  ('poruwa', 'bridal_dresser', 'BRIDAL DRESSER', 'risk'::vendor_question_group, 15, 'Deposit and cancellation terms', 'Get it in writing.'),
  ('poruwa', 'saree_dress_designer', 'SAREE / DRESS DESIGNER', 'money'::vendor_question_group, 1, 'Is this price to buy or to hire? What is the difference?', 'Hiring can be a third of the price - and comes with conditions.'),
  ('poruwa', 'saree_dress_designer', 'SAREE / DRESS DESIGNER', 'money'::vendor_question_group, 2, 'Alteration charge after the final fitting', 'Weight changes happen. Know the cost.'),
  ('poruwa', 'saree_dress_designer', 'SAREE / DRESS DESIGNER', 'money'::vendor_question_group, 3, 'If hiring - security deposit, return date, late fee and damage charges', 'Get every number in writing before you take it away.'),
  ('poruwa', 'saree_dress_designer', 'SAREE / DRESS DESIGNER', 'money'::vendor_question_group, 4, 'Price for the going-away outfit as a package', 'Usually cheaper bundled.'),
  ('poruwa', 'saree_dress_designer', 'SAREE / DRESS DESIGNER', 'included'::vendor_question_group, 5, 'Exactly which fabric - can we see and feel it before ordering?', 'Photographs hide fabric weight and drape.'),
  ('poruwa', 'saree_dress_designer', 'SAREE / DRESS DESIGNER', 'included'::vendor_question_group, 6, 'Is the blouse included, with the beading and stone work shown?', 'Frequently a separate charge.'),
  ('poruwa', 'saree_dress_designer', 'SAREE / DRESS DESIGNER', 'included'::vendor_question_group, 7, 'How many fittings are included, and when are they scheduled?', 'Three is normal. One is not enough.'),
  ('poruwa', 'saree_dress_designer', 'SAREE / DRESS DESIGNER', 'included'::vendor_question_group, 8, 'Do they supply the petticoat, falls and pins?', 'Small items, but you need them on the morning.'),
  ('poruwa', 'saree_dress_designer', 'SAREE / DRESS DESIGNER', 'included'::vendor_question_group, 9, 'Can they make the bridesmaids'' outfits to match?', 'Matching dye lots are much easier from one supplier.'),
  ('poruwa', 'saree_dress_designer', 'SAREE / DRESS DESIGNER', 'logistics'::vendor_question_group, 10, 'Delivery date - how many days before the wedding?', 'Insist on at least 7 days, not the night before.'),
  ('poruwa', 'saree_dress_designer', 'SAREE / DRESS DESIGNER', 'logistics'::vendor_question_group, 11, 'Do they provide a dresser on the day, or coordinate with the makeup artist?', 'Someone must actually drape it.'),
  ('poruwa', 'saree_dress_designer', 'SAREE / DRESS DESIGNER', 'logistics'::vendor_question_group, 12, 'Can we see a finished piece from a recent bride, in person?', 'Studio samples are not what gets delivered.'),
  ('poruwa', 'saree_dress_designer', 'SAREE / DRESS DESIGNER', 'risk'::vendor_question_group, 13, 'What happens if it is not ready on time?', 'Ask directly and note the answer.'),
  ('poruwa', 'saree_dress_designer', 'SAREE / DRESS DESIGNER', 'risk'::vendor_question_group, 14, 'Payment schedule, and how much is due before delivery', 'Never pay the full amount before the final fitting.'),
  ('poruwa', 'jewellery', 'JEWELLERY', 'money'::vendor_question_group, 1, 'Price to buy, to hire, and the difference', 'Hiring a bridal set is normal and much cheaper.'),
  ('poruwa', 'jewellery', 'JEWELLERY', 'money'::vendor_question_group, 2, 'If hiring - deposit, return deadline, late fee and loss liability', 'You are liable for a large sum. Know the exact terms.'),
  ('poruwa', 'jewellery', 'JEWELLERY', 'money'::vendor_question_group, 3, 'Buy-back or exchange policy if purchasing', 'Affects the real cost of buying over hiring.'),
  ('poruwa', 'jewellery', 'JEWELLERY', 'included'::vendor_question_group, 4, 'Real gold, gold plated or costume? What karat?', 'Get this in writing on the invoice.'),
  ('poruwa', 'jewellery', 'JEWELLERY', 'included'::vendor_question_group, 5, 'Is there a certificate or valuation?', 'Needed for insurance and for resale.'),
